mapper.select:
SELECT bom_id AS bomId, son_no AS sonNo, bom_ver AS bomVer, father_id AS fatherId, f_material_name AS fMaterialName, data_status AS dataStatus, son_id AS sonId, s_material_name AS sMaterialName, unit, fenzi, fenmu, loss_rate AS lossRate, lead_time AS leadTime, sub_cost AS nodeCost, is_valid AS isValid, create_time AS createTime FROM `清洗_物料清单主数据`
AND is_valid = #{isValid}
AND (f_material_name LIKE CONCAT('%', #{keyword}, '%') OR s_material_name LIKE CONCAT('%', #{keyword}, '%') OR father_id LIKE CONCAT('%', #{keyword}, '%') OR son_id LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY bom_id DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE `清洗_物料清单主数据`
son_no = #{sonNo}, bom_ver = #{bomVer}, father_id = #{fatherId}, f_material_name = #{fMaterialName}, data_status = #{dataStatus}, son_id = #{sonId}, s_material_name = #{sMaterialName}, unit = #{unit}, fenzi = #{fenzi}, fenmu = #{fenmu}, loss_rate = #{lossRate}, lead_time = #{leadTime}, sub_cost = #{nodeCost},
WHERE bom_id = #{bomId}
